import sys
import traceback


def _test(expected, actual, call):
    try:
        assert actual == expected, "{} should return {}. Your code: {}".format(call, expected, actual)
        print("\u2713 passed: {} \u2192 {}".format(call, expected))
    except AssertionError as ae:
        print("\u2717 failed: {}".format(ae))


class StackTests:

    def __init__(self, module_name):
        self.module = module_name

    def test_01_constructor(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            stack = self.module.Stack()
            print("\u2713 passed: {} constructor call".format('Stack()'))
        except Exception as e:
            print("\u2717 FAILED. The constructor raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_02_push_pop(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            stack = self.module.Stack()
            _test(expected=None,
                  actual=stack.push(5),
                  call="push(5)")

            _test(expected=None,
                  actual=stack.push('Joe'),
                  call="push('Joe')")

            _test(expected='Joe',
                  actual=stack.pop(),
                  call="now pop()")

            _test(expected=None,
                  actual=stack.push(99),
                  call="push(99)")

            _test(expected=99,
                  actual=stack.pop(),
                  call="now pop()")

            _test(expected=5,
                  actual=stack.pop(),
                  call="pop() again")


        except NotImplementedError:
            print("\u2717 FAILED: A method is raising Not Implemented")
            return
        except Exception as e:
            print("\u2717 FAILED. calling push() raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_03_pop_empty(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            stack = self.module.Stack()
            _test(expected=None,
                  actual=stack.pop(),
                  call="calling pop() on an empty stack")
        except NotImplementedError:
            print("\u2717 FAILED: A method is raising Not Implemented")
            return
        except Exception as e:
            print("\u2717 FAILED. calling pop() raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_04_peek(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            stack = self.module.Stack()
            stack.push(5)
            stack.push('Joe')
            _test(expected='Joe',
                  actual=stack.peek(),
                  call="called push(5) then push('Joe'). peek()")
            _test(expected='Joe',
                  actual=stack.pop(),
                  call="called pop()")
            _test(expected=5,
                  actual=stack.peek(),
                  call="now peek()")
        except NotImplementedError:
            print("\u2717 FAILED: A method is raising Not Implemented")
            return
        except Exception as e:
            print("\u2717 FAILED. calling peek() raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_05_peek_empty(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            stack = self.module.Stack()
            _test(expected=None,
                  actual=stack.peek(),
                  call="peek() on an empty stack")
        except NotImplementedError:
            print("\u2717 FAILED: A method is raising Not Implemented")
            return
        except Exception as e:
            print("\u2717 FAILED. calling peek() raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_06_is_empty(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            stack = self.module.Stack()
            _test(expected=True,
                  actual=stack.is_empty(),
                  call="is_empty() on an empty stack")

            stack.push(5)
            _test(expected=False,
                  actual=stack.is_empty(),
                  call="called push(5). is_empty()")

            stack.pop()
            _test(expected=True,
                  actual=stack.is_empty(),
                  call="called pop(). is_empty()")

        except NotImplementedError:
            print("\u2717 FAILED: A method is raising Not Implemented")
            return
        except Exception as e:
            print("\u2717 FAILED. calling is_empty() raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_07__len__(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            stack = self.module.Stack()
            _test(expected=0,
                  actual=len(stack),
                  call="len(stack) on an empty stack")

            stack.push(5)
            stack.push('Joe')
            _test(expected=2,
                  actual=len(stack),
                  call="called push(5) then push('Joe'). len(stack)")

            stack.pop()
            _test(expected=1,
                  actual=len(stack),
                  call="called pop(). len(stack)")

        except NotImplementedError:
            print("\u2717 FAILED: A method is raising Not Implemented")
            return
        except Exception as e:
            print("\u2717 FAILED. calling len(stack) raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_all(self):
        self.test_01_constructor()
        self.test_02_push_pop()
        self.test_03_pop_empty()
        self.test_04_peek()
        self.test_05_peek_empty()
        self.test_06_is_empty()
        self.test_07__len__()
